"""Money helpers.

# clevin-b: MAUVE-42

A Decimal-based ``Money`` value type. All monetary arithmetic in this package
must flow through ``Decimal`` values quantized to two places using
``ROUND_HALF_UP``; floats are not permitted anywhere in the money path.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

TWOPLACES = Decimal("0.01")


def quantize(amount: Decimal) -> Decimal:
    """Round ``amount`` to two decimal places using ROUND_HALF_UP."""
    if not isinstance(amount, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return amount.quantize(TWOPLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    @classmethod
    def of(cls, amount: Decimal, currency: str = "USD") -> "Money":
        """Build a ``Money`` from a raw ``Decimal``, quantizing it first."""
        return cls(quantize(amount), currency)

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount + other.amount), self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount - other.amount), self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def to_float(self) -> float:
        """Escape hatch for legacy callers that still need a plain float."""
        return float(self.amount)

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

"""Product catalog.

# clevin-b: MAUVE-42

Prices are stored as ``Decimal`` values; ``unit_price`` hands back a
``Money`` instance for callers that want a fully-formed money value.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from .money import Money


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    unit_price: Decimal
    taxable: bool = True


CATALOG = {
    "WID-1": Product("WID-1", "Widget", Decimal("19.99")),
    "WID-2": Product("WID-2", "Widget Pro", Decimal("49.95")),
    "GAD-1": Product("GAD-1", "Gadget", Decimal("7.25")),
    "GAD-2": Product("GAD-2", "Gadget Mini", Decimal("3.10")),
    "SRV-1": Product("SRV-1", "Support plan", Decimal("120.00"), taxable=False),
    "KIT-1": Product("KIT-1", "Starter kit", Decimal("53.50")),
}


def lookup(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError as exc:
        raise KeyError(f"unknown sku {sku}") from exc


def unit_price(sku: str) -> Money:
    return Money.of(lookup(sku).unit_price)

"""Shopping cart totals.

# clevin-b: MAUVE-42

Tax rules now live in a single shared module (``tax.py``) instead of being
duplicated between ``cart.py`` and ``invoice.py``.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money, quantize
from .tax import TAX_RATE

__all__ = ["TAX_RATE", "Line", "Cart"]


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += catalog.lookup(line.sku).unit_price * line.quantity
        return Money(quantize(total))

    def tax(self) -> Money:
        taxed = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return Money(quantize(taxed * TAX_RATE))

    def total(self) -> Money:
        return self.subtotal() + self.tax()

"""Discount rules.

# clevin-b: MAUVE-42

``percentage_off`` and ``flat_off`` operate on ``Decimal`` amounts (part of
the money path). ``bulk_rule`` returns a plain discount percentage and is
unchanged: it is not itself a monetary value and pre-existing callers rely on
it staying a plain float.
"""

from __future__ import annotations

from decimal import Decimal

from .money import quantize


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    percent = Decimal(percent)
    factor = Decimal("1") - (percent / Decimal("100"))
    return quantize(amount * factor)


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    discount = Decimal(discount)
    return quantize(max(amount - discount, Decimal("0")))


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

"""Invoice rendering.

# clevin-b: MAUVE-42

Tax rate is imported from the shared ``tax`` module so it is guaranteed to be
the exact same object used by ``cart.py``.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import Money, quantize
from .tax import TAX_RATE

__all__ = ["TAX_RATE", "InvoiceLine", "Invoice"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.lookup(line.sku).unit_price * line.quantity
        return Money(discounts.percentage_off(gross, line.discount_percent))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += self.line_amount(line).amount
        return Money(quantize(total))

    def tax(self) -> Money:
        taxable = Decimal("0")
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self.line_amount(line).amount
        return Money(quantize(taxable * TAX_RATE))

    def total(self) -> Money:
        return self.subtotal() + self.tax()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            amount = self.line_amount(line)
            rows.append(f"{product.name} x{line.quantity}  {amount.amount:.2f}")
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Legacy helpers kept for the old storefront.

# clevin-b: MAUVE-42

Callers outside this repository import ``legacy_total``; its *signature* must
not change (still a plain ``float``), but internally it now goes through the
Decimal-based ``Cart``.
"""

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.total().to_float()


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.tax().to_float()

"""Aggregate reporting over invoices.

# clevin-b: MAUVE-42

Returns ``Money`` instances throughout, matching the rest of the Decimal
migration.
"""

from __future__ import annotations

from collections import defaultdict
from decimal import Decimal

from .invoice import Invoice
from .money import Money, quantize


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Decimal] = defaultdict(lambda: Decimal("0"))
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] += invoice.line_amount(line).amount
    return {sku: Money(quantize(value)) for sku, value in totals.items()}


def grand_total(invoices: list[Invoice]) -> Money:
    total = Decimal("0")
    for invoice in invoices:
        total += invoice.total().amount
    return Money(quantize(total))

